(ns digdir.setup.config "Interactive setup wizard for initial system configuration." (:require [digdir.config.db :as config-db] [digdir.config.ops.bootstrap :as config-bootstrap] [digdir.config.ops.global :as global-ops] [digdir.config.core :as config-core] [digdir.config.deployment-specific :as deployment-specific] [digdir.setup.common :as setup-common]))

(defn ensure-config-definition!
  "Ensure a config definition exists with the expected metadata.

   This uses upsert semantics so schema-evolution fields like :config-def/root
   can be backfilled onto existing definitions.

   `:deployment-specific?` is STAMPED HERE rather than written on each of the
   forty `services.*` definition maps, so the per-path decision lives in one
   reviewable table (`digdir.config.deployment-specific`) instead of forty
   scattered flags. An explicit value in `opts` still wins, so a caller can
   override; nothing does today."
  [path opts]
  (let [conn (config-db/get-conn)]
    (config-db/upsert-definition!
      conn
      (merge {:path path
              :deployment-specific? (deployment-specific/deployment-specific? path)}
             opts))))

(declare ensure-all-config-definitions!)

(defn set-global-config!
  "Set a setup-time platform config value. Routes inherit-owned paths to the
   __global__ tenant (one source of truth for all tenants); fork-owned paths
   land in the __platform-defaults__ seed tree."
  [path value]
  (ensure-all-config-definitions!)
  (let [conn (config-db/get-conn)
        definition (config-db/get-definition @conn path)
        inherit? (= :inherit (:config-def/ownership definition))]
    (if inherit?
      (global-ops/set-global-value! conn
                                    {:path path
                                     :value value
                                     :changelog "setup-time write"
                                     :master-key (config-core/get-master-key)})
      (config-bootstrap/bootstrap-config-tree! conn
                                               {:root :platform
                                                :tenant setup-common/platform-defaults-tenant
                                                :tenant-name "Platform Defaults"
                                                :created-by "setup"
                                                :single-node? true
                                                :base-values {path value}
                                                :master-key (config-core/get-master-key)}))))

