(defn ensure-skill-config-definitions! "Ensure runtime skill config definitions exist in the database." [] (ensure-config-definition! "skills.query-planner.enabled" {:root :runtime, :value-type :boolean, :description "Skill property: enable query planning", :category :skills, :service :llm, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.query-planner.prompt" {:root :runtime, :value-type :string, :multiline? true, :description "Skill property: query planner prompt template", :category :skills, :service :llm, :sensitivity :internal, :function :prompts}) (ensure-config-definition! "skills.query-planner.max-phrases" {:root :runtime, :value-type :number, :description "Skill property: max search phrases to generate", :category :skills, :service :llm, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.query-planner.expansion-mode" {:root :runtime, :ownership :inherit, :value-type :string, :description "Skill property: query expansion mode — \"blind\", \"corpus-aware-1hop\", or \"corpus-aware-2hop\". Corpus-aware modes harvest real corpus vocabulary from the phrases collection (PRF) and ground the expansion on it. Production default is corpus-aware-2hop (set in build-skill-params-from-config); set \"blind\" per tenant/dataset to opt out — recommended for org-tagged corpora pending per-corpus validation, since auto-filter can interact with the expanded queries.", :category :skills, :service :llm, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.phrase-gen-prompt" {:root :runtime, :value-type :string, :multiline? true, :description "Skill property: phrase generation prompt template", :category :skills, :service :llm, :sensitivity :internal, :function :prompts}) (ensure-config-definition! "skills.retrieval.top-k" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property: number of chunks to retrieve before reranking", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.max-per-document" {:root :runtime, :value-type :number, :description "Skill property: max candidate chunks allowed per source document", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.query-aware-boost" {:root :runtime, :value-type :boolean, :description "Skill property: enable query-aware candidate prioritization", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.auto-filter" {:root :runtime, :value-type :boolean, :description "Skill property: add a filter detected from organisation and year names in the query. Default true.", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.strategy-weights" {:root :runtime, :value-type :edn, :description "Skill property: per-strategy merge weights, e.g. {:phrase 1.0 :content 0.5 :metadata 0.5}", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.strategy-contribution-caps" {:root :runtime, :value-type :edn, :description "Skill property: per-strategy contribution caps, e.g. {:phrase 2 :content 1}", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.title-fields" {:root :runtime, :ownership :inherit, :value-type :edn, :description "Skill property: list of doc-collection field names to query with the :doc-title strategy. Empty / absent disables the strategy. Fields must exist on the docs collection schema. Example: [\"linktitle\" \"frontmatter_title\"]", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.doc-title-chunk-fanout" {:root :runtime, :value-type :number, :description "Skill property: per-matched-doc chunk fanout K for the :doc-title strategy. Default 3 if not set.", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.chunk-content-fields" {:root :runtime, :ownership :inherit, :value-type :edn, :description "Skill property: list of chunk-collection field names to query with the :content strategy. Defaults to [\"content_markdown\"] when absent. For per-language stemmed corpora use [\"content_markdown_en\" \"content_markdown_nb\"].", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.chunk-metadata-fields" {:root :runtime, :ownership :inherit, :value-type :edn, :description "Skill property: list of chunk-collection field names to query with the :metadata strategy. Defaults to [\"metadata\"] when absent. For per-language stemmed corpora use [\"metadata_en\" \"metadata_nb\"].", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.auto-filter-rules" {:root :runtime, :ownership :inherit, :value-type :edn, :description "Skill property: ordered list of auto-filter rule specs. Each rule self-describes its type, target field, and parameters. Supported types: see digdir.rag.auto-filter-rules. Empty / absent preserves the prior org+year-only auto-detection behavior.", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.enrichment-types" {:root :runtime, :ownership :inherit, :value-type :string, :description "Skill property: comma-separated enrichment collections to search as sibling strategies — any of \"hypothetical-questions\", \"verified-phrases\", \"fact-assertions\". Empty/absent (default) = OFF. Enable ONLY for datasets whose enrichment collections exist (otherwise retrieval searches a missing collection); enable per tenant/dataset.", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.merge-mode" {:root :runtime, :ownership :inherit, :value-type :string, :description "Skill property: rank-fusion mode for merging per-strategy results. Accepts :weighted-sum (default; min-max normalized weighted-sum) or :rrf (Reciprocal Rank Fusion, Cormack et al. SIGIR 2009; pool-size invariant).", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.rrf-k" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property: RRF smoothing constant. Default 60 (matches Cormack et al. and Elasticsearch). Smaller k spreads more between top and bottom ranks. Only consulted when merge-mode is :rrf.", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.user-intent-union.enabled" {:root :runtime, :ownership :inherit, :value-type :boolean, :description "Skill property (slice 23): when true AND the planner emits a distinct :user-intent, retrieval runs a second pass with the intent string only and union-merges the two reranked outputs. Off by default; enabled per-tenant.", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.user-intent-union.mode" {:root :runtime, :ownership :inherit, :value-type :string, :description "Skill property (slice 23): union mode. One of :cap (default; slice-22 winner), :interleave (slice-21 alternating zip), or :rrf (Reciprocal Rank Fusion).", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.user-intent-union.cap" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (slice 23): cap-mode N. Intent pass's first N chunks lock into the merged head. Default 3.", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.retrieval.user-intent-union.rrf-k" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (slice 23): RRF smoothing constant for the user-intent union. Only consulted when mode is :rrf. Default 60.", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.enabled" {:root :runtime, :value-type :boolean, :description "Skill property: enable ColBERT reranking", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.top-k" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property: number of chunks to rerank", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.context.min-chunks" {:root :runtime, :value-type :number, :description "Skill property: minimum context chunks when adaptive score threshold is enabled", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.context.relative-score-threshold" {:root :runtime, :value-type :number, :description "Skill property: keep context chunks with score >= threshold * top score", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.rag.max-chunk-length" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (RAG mode): max chunk length for reranking before LLM synthesis", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.rag.max-total-length" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (RAG mode): max total length for reranking before LLM synthesis", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.rag.max-context-length" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (RAG mode): max total length for the final context window", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.rag.context.top-k" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (RAG mode): top-k chunks for the context window", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.rag.context.max-chunk-length" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (RAG mode): max chunk length for context assembly", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.retrieval.max-chunk-length" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (retrieval-only): max chunk length for raw chunk return", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.retrieval.max-total-length" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (retrieval-only): max total length for raw chunk return", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.retrieval.max-context-length" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (retrieval-only): max total length for the final context window", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.retrieval.context.top-k" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (retrieval-only): top-k chunks for the context window", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.rerank.retrieval.context.max-chunk-length" {:root :runtime, :ownership :inherit, :value-type :number, :description "Skill property (retrieval-only): max chunk length for context assembly", :category :skills, :service :search, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.synthesis.model" {:root :runtime, :ownership :inherit, :value-type :string, :description "Skill property: synthesis model override", :category :skills, :service :llm, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.synthesis.temperature" {:root :runtime, :value-type :number, :description "Skill property: synthesis temperature override", :category :skills, :service :llm, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.synthesis.max-tokens" {:root :runtime, :value-type :number, :description "Skill property: synthesis max tokens override", :category :skills, :service :llm, :sensitivity :internal, :function :settings}) (ensure-config-definition! "skills.synthesis.system-prompt" {:root :runtime, :value-type :string, :multiline? true, :description "Skill property: synthesis system prompt template", :category :skills, :service :llm, :sensitivity :internal, :function :prompts}) (ensure-config-definition! "skills.synthesis.generation-prompt" {:root :runtime, :value-type :string, :multiline? true, :description "Skill property: synthesis generation prompt template", :category :skills, :service :llm, :sensitivity :internal, :function :prompts}) (ensure-config-definition! "skills.synthesis.max-docs" {:root :runtime, :value-type :number, :description "Skill property: max context docs to include during synthesis", :category :skills, :service :llm, :sensitivity :internal, :function :settings}))

(defn ensure-judge-config-definitions!
  "Ensure LLM-as-judge config definitions exist (sweep answer-quality scoring)."
  []
  (ensure-config-definition! "services.judge.model"
                             {:root :platform, :ownership :inherit, :value-type :string,
                              :description "LLM-as-judge model for sweep answer-quality scoring (independent of the agent model). Default gpt-5.5. Must be routable by the configured LLM endpoint/proxy.",
                              :category :services, :service :llm, :sensitivity :internal, :function :settings})
  (ensure-config-definition! "services.judge.enabled"
                             {:root :platform, :ownership :inherit, :value-type :boolean,
                              :description "Enable LLM-as-judge scoring during sweeps. Off by default; the dashboard re-eval button judges on demand regardless.",
                              :category :services, :service :llm, :sensitivity :internal, :function :settings}))

(defn ensure-self-improvement-config-definitions!
  "Ensure config definitions for the self-improvement (enrichment-generation)
   LLM usage. Follows the `services.<usage>.provider` model-usage convention
   (cf. `services.search-phrases.provider`): a provider selector lets the
   propose-questions / propose-phrases enrichment calls be redirected to a local
   model (LM Studio via `services.lmstudio.*`) for cost, independent of the
   agent and judge models. Model + reasoning-effort overrides are usage-scoped."
  []
  (ensure-config-definition! "services.self-improvement.provider"
                             {:root :platform, :ownership :inherit, :value-type :edn,
                              :description "Which OpenAI-compatible provider drives the self-improvement enrichment-generation calls. Keyword: :azure-openai, :openrouter, or :lmstudio. Defaults to :azure-openai if unset.",
                              :category :services, :service :llm, :sensitivity :internal, :function :settings})
  (ensure-config-definition! "services.self-improvement.model"
                             {:root :platform, :ownership :inherit, :value-type :string,
                              :description "Usage-scoped model override for self-improvement enrichment generation. When set, wins over the active provider's conventional model key (e.g. services.lmstudio.model) — lets self-improvement pin a model distinct from other lmstudio usages.",
                              :category :services, :service :llm, :sensitivity :internal, :function :settings})
  (ensure-config-definition! "services.self-improvement.reasoning-effort"
                             {:root :platform, :ownership :inherit, :value-type :string,
                              :description "Optional reasoning_effort passed on self-improvement enrichment calls (e.g. \"none\", \"low\"). Reasoning-class local models otherwise spend most of the token budget on a thinking channel before emitting output. Omit for non-reasoning models.",
                              :category :services, :service :llm, :sensitivity :internal, :function :settings}))

(defn ensure-all-config-definitions! "Ensure all config definitions exist in the database.\n   This is called after import to make sure all required definitions are present." [] (println "Ensuring all config definitions exist...") (ensure-email-config-definitions!) (ensure-typesense-config-definitions!) (ensure-azure-openai-config-definitions!) (ensure-other-services-config-definitions!) (ensure-lmstudio-config-definitions!) (ensure-system-config-definitions!) (ensure-pipeline-config-definitions!) (ensure-skill-config-definitions!) (ensure-judge-config-definitions!) (ensure-self-improvement-config-definitions!) (println "  Config definitions ensured."))

(defn setup-typesense-defaults "Set up default values for Typesense configuration." [] (ensure-typesense-config-definitions!) (let [current-prefix (setup-common/get-global-config "services.typesense.collection-prefix")] (when-not current-prefix (set-global-config! "services.typesense.collection-prefix" "digdir_rag_") (println "  Set default Typesense collection prefix: digdir_rag_"))))
